from sqlalchemy import text


async def search_payments(db, user_id: int, q: str):
    stmt = text(
        f"SELECT * FROM payments WHERE user_id = :uid AND reference ILIKE '%{q}%'"
    )
    return await db.execute(stmt, {"uid": user_id})

